50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	const BLOCK_SIZE = 3;
64	
65	const BLOCK_BASE_PREMIUM = 60;
66	
67	const countByType = (items: Item[]): Map<string, number> => {
68	  const counts = new Map<string, number>();
69	
70	  for (const item of items) {
71	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
72	  }
73	
74	  return counts;
75	};
76	
77	const typeGroupBasePremiumOf = ([type, count]: [string, number]): number =>
78	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
79	
80	const policyBasePremiumOf = (items: Item[]): number =>
81	  [...countByType(items)].reduce(
82	    (sum, typeGroup) => sum + typeGroupBasePremiumOf(typeGroup),
83	    0,
84	  );
85	
86	const CURSE_SURCHARGE_RATE = 0.5;
87	
88	const curseSurchargeOf = (items: Item[]): number =>
89	  items
90	    .filter((item) => item.cursed)
91	    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE, 0);
92	
93	const quote = ({ items }: QuoteStep): QuoteResult => {
94	  const policyBase = policyBasePremiumOf(items);
95	
96	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
97	
98	  const premiumBeforeRounding =
99	    policyBase + curseSurchargeOf(items) + firstInsuranceSurcharge + PROCESSING_FEE;
100	
101	  return { premium: Math.ceil(premiumBeforeRounding) };
102	};
103	
104	const runStep = (step: Step): StepResult => {
105	  if (step.op === "quote") return quote(step);
106	
107	  throw new Error(`unsupported step: ${step.op}`);
108	};
109	
110	export const runScenario = (scenario: Scenario): ScenarioResult => ({
111	  results: scenario.steps.map(runStep),
112	});
