// Item-specific modifiers apply to the affected item's own base premium.
const itemModifiersOf = (items: Item[]): number => curseSurchargeOf(items);

// Policy-wide modifiers apply to the policy base premium, so they are computed
// from the base alone — item-specific modifiers are not part of their base.
const policyModifiersOf = (policyBase: number): number =>
  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;

const quote = ({ items }: QuoteStep): QuoteResult => {
  const policyBase = policyBasePremiumOf(items);

  const premiumBeforeRounding =
    policyBase + itemModifiersOf(items) + policyModifiersOf(policyBase) + PROCESSING_FEE;

  return { premium: Math.ceil(premiumBeforeRounding) };
};
